INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (320, 9040000, NULL, 9040007, '辨阳明病脉证并治法', 617215532572741, 'BD533880E124D6F5F5E6AEE5D8BE4A35', '人体内从胃一直到十二指肠、小肠、大肠，胃旁边的脾脏，脾脏有一个血管到胃的下方，胃下方的甜肉，中医叫做膵肉，就是西医的胰脏，中医的观念认为胰脏是脾之大络，脾之大络会在大包穴，就是在极泉下六寸，渊液下三寸，就是大包穴，所以大包穴在管胰脏；中医认为这整个系统通称为脾，脾脏的血液很多，脏里面都是藏血的，脾脏的血进入胃的下方，进入血管，让胃蠕动，然后食物进入十二指肠，胆的苦液、脾和胰的甜液、肝的酸液跑 到肠胃里面帮助消化，张仲景的处方分有大承气汤、小承气汤，和煮药的方法，如果大便堵在大肠的地方，汤药吃下的时候，第一味药把燥屎打散、第二味扫出来，因为打烂的地方很痛，所以第三味药让肠子蠕动，把痉挛缓和下来，小肠进入大肠交接的地方就是盲肠，盲肠下面有段阑尾，很多人大便堵在阑尾这一段，就是急性盲肠炎，慢性盲肠炎就是堵在盲肠这段，如何检查堵在哪里?如果脾脏的津液没有出来，是什么现象?肝汁（校对注：原文如此，疑似“胆汁”） 没有办法分泌。胃里面津液丧失太多了以后，胃里面太燥热，任何东西一遇到热 一定往上升，结果胆汁往上跑，第一个就是跑到嘴巴里面，会吐苦水，第二逆回肝脏里面，肝是全身的血脏、胆汁跑到血里面，造成全身发黄，诸如此类的，在阳明篇里面一一介绍，所谓阳明就是腑，所以阳明篇都是讲消化系统所产生的病变。  \n\n内经灵枢中与阳明篇有关的章节有师传第二十九、决气第三十、肠胃第三十一、平人绝谷第三十二、海论第三十三；可与阳明篇相互参照。  ', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-27 15:18:48', 1, '超级管理员', '2024-11-29 11:56:28');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (321, 9040000, NULL, 9040008, '辨少阳病脉证并治法', 617544981155909, 'DF0E048407E7C283D3FFAC9D926E70FC', '少阳就是所谓的神经、血脉，凡是不列入脏腑的，沟通脏腑之间的油网络，都是少阳包括西医讲的淋巴系统，如何从外症或摸脉知道病邪停在少阳，如何判断及检查?就是此少阳篇要介绍的。病邪在皮肤表面的时候，皮表就是太阳，如果来不及用桂枝或葛根汤等去发汗，病邪脱离皮表进入少阳，代表滤过性病毒进入淋巴系统，也就是进入水道系统。就是中医所谓的气。没有入腑，入腑就是阳明证，也没有入脏，入脏就是少阴或厥阴，如何检查及判断？少阳有什么主症？临床上，常常病人感冒的时候，本来是太阳证，一吃抗生素，就变成少阳，抗生素没有把滤过性病毒杀掉，反而对肠胃功能有伤害，所以西药大多要饭后吃，因为西药伤胃，中药都是空腹，中药要饭后吃是希望药停在上面，所以像去胸中烦躁的栀子豉汤就可以饭后吃。  \n\n人身上最主要、最密的血脉神经就是在胸腔、横膈膜、纵膈膜这一带，包括肺和心，所以进来的时候会进入这地方。人的眼、耳、目、口、鼻，所有的五官有问题的时候，化脓等都属于三焦系统，就是所谓的少阳系统，而像耳朵的功能有障碍，肾开窍在耳，就属于内脏的问题。而本身发生的病症就是在半表半里的中间。在表的里，在里之外。例：女人的乳癌细胞在淋巴系统的时候，还可以治疗，在血脉神经的时候也还可以治疗，可是如果转移到骨或脏的时候，就晚了。  ', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 15:29:07', 1, '超级管理员', '2024-11-30 10:17:00');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (322, 9040000, NULL, 9040009, '辨太阴病脉证并治法 ', 617565182881861, '1E9FC5A57C1329BB4EDF3E0FA5B79C63', '      太阴叫做始阴，少阴是阴之中，厥阴是阴之尽，阴的尽头。刚开始进到少阴，到了厥阴还没治好就危险了，中医就是想尽办法让三阴不受邪，刚开始都是太阴，所以张仲景开处方的时候，不管病进入少阴、厥阴，随时都顾虑到太阴的问题，因为始受病在太阴。  \n\n        太阴就是脾脏，病会进入脾脏的人，一般来说是胃弱掉的人，中医的观念脾胃相表里，脾胃是后天之主，后天好的人脾胃就很好，我们的免疫系统就是在这里，所以免疫系统始萌在脾胃，吃到食物下来到胃里面的时候，脾脏开始蠕动，胃一撑满把脾脏压小了，脾脏一压小，脾脏的血就跑到胃下方的甜肉，就是胰脏，胰脏一充血的时候，血又跑到胃的下方，胃就开始蠕动，一蠕动产生热能，胃热起来了，胃一热起来就开始消化食物，然后把食物灌到四肢为身体所受用，这胃也包括小肠。  \n\n        有一天，胃太弱了。消化力不好，胃弱的原因就是脾脏跑到胃下方的血热度不够了，动能不够，食物在胃里面蒸化腐化掉了，可是并没有被人所完全吸收，这食物的津液怎么看?谷物本来是干干的，盖起来发酵后成白白的津液，这津液就是人能吸收的津液，如果滤过性病毒跑到脾脏里面去了，食物磨碎了，但是没有完全消化，旧的食物停着，新的食物下不去，所以得病的病人胃口都不是很好，脾在横膈膜的中间，脾脏在右边，肝脏在左边，病毒进入三焦淋巴系统还没有好的时候，就进入脾脏了，旧的食物产生的营养，身体又不能受用，这白色的津液越积越多，累积起来，脾的湿气就越来越盛，脾有一定的湿度，因为津液没有办法消化掉，停着慢慢就盛起来了，脾湿就越来越大，脾脏就越来越大，脾脏一肿大，恶性循环，胃就越来越小，胃是被挤小的，所以脾脏大的人会恶心，吐出来的都是白色的津液，下利也是湿的，溏的，这就是津液没有办法消化，就是西医讲的高蛋白，所以腹水的水都是营养液，因为功能丧失掉了，吸收不了，这功能丧失是日积月累下来的，所以十几二十年得病还没有死，如何把这津液排出去，就是治疗脾脏的观念，排津液的同时，要把胃加强起来，因为胃弱会让脾脏的功能不好，脾脏肿大会让胃弱，这是恶性循环的，肇因就是先病在少阳没有治好，让它进来，所以平常胃不好的人就要调理好，刚开始就用小建中汤调理，不要等到脾脏大了之才治疗。  ', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-29 16:13:10', 1, '超级管理员', '2024-11-30 11:39:12');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (323, 9040000, NULL, 9040010, '辨少阴病脉证并治法', 618276177297477, '67BA89BEF615ACEDF3897E39EB3C08FC', '       手少阴心经，足少阴肾经为少阴二脏，心脏有一条大动脉出来、一条大静脉血管回来心脏，从心脏到肾脏血脉是相交的，心和肾要通的时候是靠中间的脾胃，有一天脾脏有问题，太阴先受病，太阴病没好，如果脾脏没有好，让上下没有办法通利，血液循环就不是很好，因而造血的功能就不行了。心本身血就不足了，心血不足的时候，血脉很弱很细很微，所以少阴证出来第一个脉是很微很细的，吸收营养功能不够的时候，会表现在我们精神上面，精神的来源，精神很好，代表血气很旺，讲话细细的有气无力，精神不够，就是神不足，就是但欲寐，少阴病完全是又阴又寒，一旦吸收食物营养不够，生成血的能量不够了，所有内脏的功能都因之缓下来了，等于没有蠕动，整个不动停滞，如果说太阴病没好，进入少阴证，人就很虚弱。  ', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-11-30 11:40:20', 1, '超级管理员', '2024-12-02 11:52:14');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (324, 9040000, NULL, 9040011, '辨厥阴病脉证并治法  ', 618581241217093, '9F7E173F5AFDC465C30CF97102C22808', '      厥阴主要谈的就是肝，附属的就是心包、手厥阴心包经、足厥阴肝经，所以看到厥阴证，手足四逆的时候，心脏一定衰弱了，因为心血不足，肝又不受血了，病从太阴进入少阴，到了少阴没有好，所有的病毒会进入厥阴，这是人体最后一道关卡，人身上有五分之一的血在肝里面，像现在的急性肝炎、从饮食来的或输血来的，病毒随着血就到肝里面去了，肝能把血里面的毒代谢掉，把脏的排出去，因为五脏六腑所有的血通通会进入肝，从肝的静脉出来，再到胸腔再交换，厥阴证里面方子不多，轻微的有用到皮肤表面，重病的时候，汤方一样，只是剂量加重，像冻疮，热水敷都没有用，因为老是表热但里面仍是冷的，用当归四逆汤，能从脚指头发热出来，因为有新鲜的血进入了。  \n\n       到了最后很危险的阶段，人的免疫系统会出来相抗，就是肝脏的血会出来相抗，因为里面很深的地方，赢的时候病人会发热，输了病人就昏迷过去了，所以寒热并见，而且可以看到很多昏迷的现象，因为完全在血里面，东西淤积在肝里面，结果造成血液循环产生障碍，所以有昏厥的现象。  ', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '超级管理员', '2024-12-02 11:54:43', 1, '超级管理员', '2024-12-03 08:33:33');
