INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (437, 9020000, NULL, 9020006, '第四章、贰、中经 $a{本草经卷二，吴普等述，孙星衍，冯翼同辑。 中经一百二十种为臣，主养性，以应人，无毒有毒斟酌其宜，欲去病补羸者本中经。}', 633920418689093, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-15 16:48:49', 1, 'admin', '2025-01-17 13:36:34');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (438, 9020000, NULL, 9020008, '第五章、叁、下经 $a{本经下药一百二十五种为佐使，主治病以应地，多毒不可久服，欲除寒热邪气，破积聚愈疾者，本下经。  }', 634246871048261, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-16 14:57:10', 1, 'admin', '2025-01-17 16:43:54');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (439, 9020000, NULL, 9020010, '第五章  增补神农本草经不足部分', 634628414627909, NULL, '以下的药物原不见于神农本草经，但是因为张仲景医圣在伤寒与金匮中有使用到这些药物，我想必然在仲师所依循的胎胪药录该书之中可以找到，由于该书已经失传，我不揣冒昧地将它们另外列出，并附上使用说明，以求使经方更为完善。  ', 1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-17 16:49:40', 1, 'admin', '2025-01-17 17:24:22');
