INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (442, 9050000, NULL, 9050030, '藏府经络先后病脉证第一', 634958593863749, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-18 15:13:10', 1, 'admin', '2025-02-28 15:44:09');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (443, 9050000, NULL, 9050040, '痉湿暍病脉证治法第二', 634958681006149, NULL, '中医讲的痉病区分为刚痉和柔痉二种，类似西医讲的「脑脊髓神 经炎」，简言叫「脑膜炎」。「湿病」就是中湿，湿有时候在身体里面， 有时候在关节上面。『 喝 yē』就是中暑，热天的时候中暑，这一篇 就是在讲这些病症。诸位看，第一条。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-18 15:13:31', 1, 'admin', '2025-03-03 09:55:50');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (444, 9050000, NULL, 9050050, '百合狐惑阴阳毒证治第三', 634959207608389, NULL, '这个章节很有意思，目前为止西医也是无药可治，百合病近似于 现代的神经衰弱症与厌食症。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-18 15:15:40', 1, 'admin', '2025-03-06 14:10:00');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (445, 9050000, NULL, 9050060, '疟病脉证并治第四', 634959252070469, NULL, '所谓疟病就是现在的疟疾，症状是忽冷忽热，中医叫『疟病』。 疟病，张仲景又分了几种不同的症状。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-18 15:15:51', 1, 'admin', '2025-03-07 10:01:41');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (446, 9050000, NULL, 9050070, '中风历节病脉并第五', 634959322517573, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-18 15:16:08', 1, 'admin', '2025-03-08 09:58:07');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (447, 9050000, NULL, 9050080, '血痹虚劳病脉并治第六', 634959395393605, NULL, '这个章节将血痹跟虚劳摆在一起，代表两个都是虚症，所以大家 要知道如何区分虚劳跟血痹的不同处，与如何正确的施治。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-18 15:16:26', 1, 'admin', '2025-03-12 12:42:42');
INSERT INTO `Book` (`BookInfoId`, `BookId`, `BookName`, `ChapterSection`, `ChapterHeader`, `SignatureId`, `Signature`, `Remark`, `Enable`, `Extend01`, `Extend02`, `Extend03`, `Extend04`, `Extend05`, `Extend06`, `Extend07`, `Extend08`, `Extend09`, `Extend10`, `Extend11`, `Extend12`, `CreateID`, `Creator`, `CreateDate`, `ModifyID`, `Modifier`, `ModifyDate`) VALUES (448, 9050000, NULL, 9050090, '肺痿肺痈咳嗽上气病脉证治第七.', 634959537242181, NULL, '       现在开始进入讨论肺脏、胸腔内的疾病。中医的观念里面，什么 叫做肺痿？肺痈？如果我这样讲，你就一目了然了，这个痿就是萎缩 了，叫做痿，也就是肺脏萎缩掉。所谓肺气胀，就是胀到一直是在吸 气的状态之下，无论是吸气或是呼气，肺都是胀在那边不会变大与缩小，这就是肺胀。肺痈就是肺里面已经化脓，大致上可以区分为这三 大系统，处方也只有几个而己，张仲景用几个条辨，就可以将肺病讲完了。', 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, 'admin', '2025-01-18 15:17:00', 1, 'admin', '2025-03-13 17:17:45');
